package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeFactory._fromVariable
 */
public class TypeFactory__fromVariable_TriageGen0Test {

    private TypeFactory _typeFactory;
    private TypeVariable<?> _mockTypeVariable;
    private TypeBindings _mockContext;

    @Before
    public void setUp() {
        _typeFactory = TypeFactory.defaultInstance();
        _mockTypeVariable = mock(TypeVariable.class);
        _mockContext = mock(TypeBindings.class);
    }

    /**
     * Test Case 1: context is null.
     * Should return _unknownType().
     */
    @Test
    public void test_fromVariable_contextNull() throws Exception {
        // Since _fromVariable is protected, we use a subclass or reflection if it were truly inaccessible,
        // but in the context of this exercise, we assume accessibility or use a test-subclass.
        // For the purpose of this test, we access it via a wrapper or assume visibility in the package.

        TypeFactory testFactory = new TestableTypeFactory();
        JavaType result = testFactory.invokeFromVariable(_mockTypeVariable, null);

        assertEquals(JavaType.unknownType(), result);
    }

    /**
     * Test Case 2: context is not null, and context.findType(name) returns a valid JavaType.
     * Should return the found JavaType.
     */
    @Test
    public void test_fromVariable_contextFindsType() throws Exception {
        String varName = "T";
        JavaType expectedType = _typeFactory.constructSimpleType(String.class);

        when(_mockTypeVariable.getName()).thenReturn(varName);
        when(_mockContext.findType(varName)).thenReturn(expectedType);

        TypeFactory testFactory = new TestableTypeFactory();
        JavaType result = testFactory.invokeFromVariable(_mockTypeVariable, _mockContext);

        assertEquals(expectedType, result);
        verify(_mockContext, never())._addPlaceholder(anyString());
    }

    /**
     * Test Case 3: context is not null, context.findType(name) returns null.
     * Should add a placeholder and return the type constructed from the first bound.
     */
    @Test
    public void test_fromVariable_contextFindsNothing_usesBounds() throws Exception {
        String varName = "T";
        Class<?> boundClass = Number.class;

        when(_mockTypeVariable.getName()).thenReturn(varName);
        when(_mockContext.findType(varName)).thenReturn(null);
        when(_mockTypeVariable.getBounds()).thenReturn(new Type[]{boundClass});

        TypeFactory testFactory = new TestableTypeFactory();
        // We need to mock _constructType behavior or use a real one. 
        // Since _constructType is protected and part of TypeFactory, 
        // the TestableTypeFactory will call the real one.

        JavaType result = testFactory.invokeFromVariable(_mockTypeVariable, _mockContext);

        assertNotNull(result);
        assertEquals(boundClass, result.getRawClass());
        verify(_mockContext)._addPlaceholder(varName);
    }

    /**
     * Test Case 4: Verify the logic with multiple bounds (it should pick the first one).
     */
    @Test
    public void test_fromVariable_multipleBounds_picksFirst() throws Exception {
        String varName = "T";
        Type firstBound = String.class;
        Type secondBound = Integer.class;

        when(_mockTypeVariable.getName()).thenReturn(varName);
        when(_mockContext.findType(varName)).thenReturn(null);
        when(_mockTypeVariable.getBounds()).thenReturn(new Type[]{firstBound, secondBound});

        TypeFactory testFactory = new TestableTypeFactory();
        JavaType result = testFactory.invokeFromVariable(_mockTypeVariable, _mockContext);

        assertEquals(String.class, result.getRawClass());
        verify(_mockContext)._addPlaceholder(varName);
    }

    /**
     * Helper subclass to expose protected method for testing.
     */
    private static class TestableTypeFactory extends TypeFactory {

        protected TestableTypeFactory() {
            super(null, null); // Note: In a real environment, TypeParser and TypeModifier are needed.
            // Since we can't easily construct a real TypeFactory with nulls, 
            // we assume the environment allows this or we use the defaultInstance.
        }

        // Re-using defaultInstance to avoid constructor issues with nulls
        private static final TypeFactory INSTANCE = TypeFactory.defaultInstance();

        public JavaType invokeFromVariable(TypeVariable<?> type, TypeBindings context) {
            try {
                java.lang.reflect.Method method = TypeFactory.class.getDeclaredMethod("_fromVariable", TypeVariable.class, TypeBindings.class);
                method.setAccessible(true);
                return (JavaType) method.invoke(INSTANCE, type, context);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        // Overriding to ensure we use the real logic from the default instance
        @Override
        protected JavaType _fromVariable(TypeVariable<?> type, TypeBindings context) {
            try {
                java.lang.reflect.Method method = TypeFactory.class.getDeclaredMethod("_fromVariable", TypeVariable.class, TypeBindings.class);
                method.setAccessible(true);
                return (JavaType) method.invoke(TypeFactory.defaultInstance(), type, context);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }
}
